// Normalize input parameters
const input = $input.first().json || {};

const currency = String(input.currency || '').trim().toUpperCase();

const allowedImpacts = ['low', 'medium', 'high', 'all'];
let impact = String(input.impact || 'all').trim().toLowerCase();
if (!allowedImpacts.includes(impact)) impact = 'all';

const limit = Math.min(Math.max(Number(input.limit) || 8, 1), 25);
const hoursAhead = Math.min(Math.max(Number(input.hours_ahead) || 168, 1), 336);

return [{ currency, impact, limit, hours_ahead: hoursAhead }];

// Format and filter TradingFactory/ForexFactory calendar items
const normalized = $('Normalize Input').item.json;
const rawItems = $input.all().map(i => i.json).filter(Boolean);

let events = [];
if (rawItems.length === 1 && Array.isArray(rawItems[0])) {
  events = rawItems[0];
} else if (Array.isArray(rawItems)) {
  events = rawItems;
}

const normalizeImpact = (v) => {
  const s = String(v ?? '').toLowerCase();
  if (s.includes('high') || s === '3') return 'high';
  if (s.includes('med') || s === '2') return 'medium';
  if (s.includes('low') || s === '1') return 'low';
  return 'unknown';
};

const toDate = (v) => {
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? null : d;
};

const now = new Date();
const horizon = new Date(now.getTime() + normalized.hours_ahead * 60 * 60 * 1000);

const filtered = events
  .map((e) => {
    const date = toDate(e.date || e.datetime || e.timestamp);
    const impact = normalizeImpact(e.impact);
    return {
      title: e.title || e.event || 'Economic Event',
      currency: String(e.currency || e.ccy || '').toUpperCase(),
      country: e.country || null,
      impact,
      date: date ? date.toISOString() : null,
      actual: e.actual ?? null,
      forecast: e.forecast ?? null,
      previous: e.previous ?? null,
      source: 'TradingFactory',
      url: e.url || 'https://www.forexfactory.com/calendar'
    };
  })
  .filter((e) => e.date !== null)
  .filter((e) => !normalized.currency || e.currency === normalized.currency)
  .filter((e) => normalized.impact === 'all' || e.impact === normalized.impact)
  .filter((e) => {
    const d = new Date(e.date);
    return d >= now && d <= horizon;
  })
  .sort((a, b) => new Date(a.date) - new Date(b.date))
  .slice(0, normalized.limit);

return [{
  ok: true,
  source: 'TradingFactory',
  filters: normalized,
  news_count: filtered.length,
  news: filtered,
  timestamp: new Date().toISOString(),
  disclaimer: 'Economic calendar data is informational only, not financial advice.'
}];
